export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [locale, setLocaleState] = useState<string>(i18n.locale);

  useEffect(() => {
    (async () => {
      const saved = await AsyncStorage.getItem(STORAGE_KEY).catch(() => null);
      const initial = saved && SUPPORTED.includes(saved) ? saved : deviceLang();
      i18n.locale = initial;
      setLocaleState(initial);
    })();
  }, []);

  const setLocale = useCallback(async (code: string) => {
    if (!SUPPORTED.includes(code)) return;
    i18n.locale = code;
    setLocaleState(code);
    await AsyncStorage.setItem(STORAGE_KEY, code).catch(() => {});
  }, []);

  // Dépend de `locale` pour que les écrans se re-rendent au changement de langue.
  const t = useCallback((key: string, options?: Record<string, unknown>) => i18n.t(key, options), [locale]);

  const value = useMemo<Ctx>(() => ({ locale, setLocale, t }), [locale, setLocale, t]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n() {
  return useContext(I18nContext);
}

/** Raccourci quand seul t() est nécessaire. */
export function useT() {
  return useContext(I18nContext).t;
}
